INSERT INTO `e_alert_rule` VALUES (1,'R01','采集离线','quality','采集点连续 3 个周期无数据','{\"consecutive_periods\": 3}','normal',1,'2026-05-01 00:00:00',NULL,1,'K.7-R02 / G.3 第二幕（INJ-01）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(2,'R02','数据迟到','quality','批次入库时间 − 采样时间 > 15 分钟','{\"delay_minutes\": 15}','notice',1,'2026-05-01 00:00:00',NULL,1,'质量类','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(3,'R03','连续零值','quality','设备运行中且连续 4 个周期增量 = 0','{\"consecutive_periods\": 4}','normal',1,'2026-05-01 00:00:00',NULL,1,'疑似表计故障','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(4,'R04','数据跳变','quality','单周期增量 > 8× 前 4 周同时段均值','{\"multiplier\": 8, \"reference_weeks\": 4}','normal',1,'2026-05-01 00:00:00',NULL,1,'K.7-R03 / INJ-02','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(5,'R05','设备高耗偏离','energy','连续 3 小时能耗 > 同类均值 ×1.5 且作业量未同步增加','{\"hours\": 3, \"energy_multiplier\": 1.5, \"workload_delta_max\": 0}','severe',1,'2026-05-01 00:00:00',NULL,1,'K.7-R05 / G.5 第三幕（INJ-03）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(6,'R06','非作业气流量异常','energy','非作业时段气流量 > 作业均值 ×30%，持续 2 小时','{\"work_pct_threshold\": 0.3, \"duration_hours\": 2}','severe',1,'2026-05-01 00:00:00',NULL,1,'K.7-R06 / G.6 第四幕（INJ-04）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(7,'R07','空压机频繁启停','energy','1 小时内启停 ≥6 次','{\"toggles_per_hour\": 6}','normal',1,'2026-05-01 00:00:00',NULL,1,'G.6 辅证','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(8,'R08','非作业照明异常','energy','非作业时段照明回路功率 > 2kW，持续 1 小时','{\"power_kw_threshold\": 2, \"duration_hours\": 1}','notice',1,'2026-05-01 00:00:00',NULL,1,'K.7-R07 / G.8 支线（INJ-05）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(9,'R09','基线偏差','energy','日能耗超出基线带 +20%（演示态）','{\"deviation_pct\": 20}','normal',1,'2026-05-01 00:00:00',NULL,1,'总览联动 REQ-029','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(10,'R10','峰段成本占比异常','cost','成本中心峰段成本占比较基线期抬升 > 8 个百分点','{\"pct_point_threshold\": 8}','normal',1,'2026-05-01 00:00:00',NULL,1,'K.7-R10 / G.9 第五幕（INJ-06）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18'),(11,'R11','覆盖率不足','quality','日采样覆盖率 [80%,95%) 提示，< 80% 严重','{\"warn_threshold\": 0.95, \"severe_threshold\": 0.8}','notice',1,'2026-05-01 00:00:00',NULL,1,'K.7-R04 / 第二幕佐证（INJ-07 触发严重档）','datagen','datagen','2026-09-15 11:13:18','2026-09-15 11:13:18');
INSERT INTO `e_alert_rule_version` VALUES (1,1,1,'{\"code\": \"R01\", \"name\": \"采集离线\", \"expr\": \"采集点连续 3 个周期无数据\", \"thresholds\": {\"consecutive_periods\": 3}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(2,2,1,'{\"code\": \"R02\", \"name\": \"数据迟到\", \"expr\": \"批次入库时间 − 采样时间 > 15 分钟\", \"thresholds\": {\"delay_minutes\": 15}, \"level\": \"notice\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(3,3,1,'{\"code\": \"R03\", \"name\": \"连续零值\", \"expr\": \"设备运行中且连续 4 个周期增量 = 0\", \"thresholds\": {\"consecutive_periods\": 4}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(4,4,1,'{\"code\": \"R04\", \"name\": \"数据跳变\", \"expr\": \"单周期增量 > 8× 前 4 周同时段均值\", \"thresholds\": {\"multiplier\": 8, \"reference_weeks\": 4}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(5,5,1,'{\"code\": \"R05\", \"name\": \"设备高耗偏离\", \"expr\": \"连续 3 小时能耗 > 同类均值 ×1.5 且作业量未同步增加\", \"thresholds\": {\"hours\": 3, \"energy_multiplier\": 1.5, \"workload_delta_max\": 0}, \"level\": \"severe\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(6,6,1,'{\"code\": \"R06\", \"name\": \"非作业气流量异常\", \"expr\": \"非作业时段气流量 > 作业均值 ×30%，持续 2 小时\", \"thresholds\": {\"work_pct_threshold\": 0.3, \"duration_hours\": 2}, \"level\": \"severe\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(7,7,1,'{\"code\": \"R07\", \"name\": \"空压机频繁启停\", \"expr\": \"1 小时内启停 ≥6 次\", \"thresholds\": {\"toggles_per_hour\": 6}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(8,8,1,'{\"code\": \"R08\", \"name\": \"非作业照明异常\", \"expr\": \"非作业时段照明回路功率 > 2kW，持续 1 小时\", \"thresholds\": {\"power_kw_threshold\": 2, \"duration_hours\": 1}, \"level\": \"notice\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(9,9,1,'{\"code\": \"R09\", \"name\": \"基线偏差\", \"expr\": \"日能耗超出基线带 +20%（演示态）\", \"thresholds\": {\"deviation_pct\": 20}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(10,10,1,'{\"code\": \"R10\", \"name\": \"峰段成本占比异常\", \"expr\": \"成本中心峰段成本占比较基线期抬升 > 8 个百分点\", \"thresholds\": {\"pct_point_threshold\": 8}, \"level\": \"normal\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18'),(11,11,1,'{\"code\": \"R11\", \"name\": \"覆盖率不足\", \"expr\": \"日采样覆盖率 [80%,95%) 提示，< 80% 严重\", \"thresholds\": {\"warn_threshold\": 0.95, \"severe_threshold\": 0.8}, \"level\": \"notice\"}','2026-05-01 00:00:00',NULL,'datagen','2026-09-15 11:13:18');
